export function Testimonial({
  quote = "{{quote}}",
  name = "{{name}}",
  role = "{{role}}",
  accent = "{{accent}}",
}) {
  return (
    <figure style={{ font: "16px/1.5 system-ui, sans-serif", color: "#241430", maxWidth: 340, margin: 0, padding: 22,
      borderRadius: 14, background: "#FAF7F2", border: "1px solid #24143022" }}>
      <blockquote style={{ margin: "0 0 16px", fontSize: 17, fontWeight: 500 }}>&ldquo;{quote}&rdquo;</blockquote>
      <figcaption style={{ display: "flex", alignItems: "center", gap: 10 }}>
        <span aria-hidden="true" style={{ display: "inline-flex", alignItems: "center", justifyContent: "center",
          width: 38, height: 38, borderRadius: "50%", fontSize: 12, fontWeight: 700, flexShrink: 0, background: accent }}>SW</span>
        <span><strong style={{ fontSize: 14 }}>{name}</strong><br /><span style={{ fontSize: 13, color: "#241430aa" }}>{role}</span></span>
      </figcaption>
    </figure>
  );
}
